-- CMS S1 (DP-015, ADR-020): pages of the two public sites, draft only.
--
-- Runs as dp_owner (ADR-012A). Additive only: one enum, one table, CHECK constraints. No existing
-- table, column or row is changed. dp_app receives SELECT, INSERT, UPDATE through the default
-- privileges of ADR-012A; DELETE is withdrawn (S1 has no page deletion). Publication, revisions
-- and preview arrive in S2 with their own migration.
--
-- Part 1 is generated by `prisma migrate diff --from-schema <main> --to-schema schema.prisma`.
-- Part 2 adds the rules Prisma cannot model; test/integration/cms.int.test.ts covers each one.
-- Like the catalogue tables, CmsPage is site-bound through the site-scoped client (ADR-011
-- section 4) and has no row-level security (ADR-020 D5).

-- ===========================================================================================
-- Part 0: preconditions
-- ===========================================================================================

DO $$
DECLARE
  missing text;
BEGIN
  SELECT string_agg(r, ', ')
  INTO missing
  FROM unnest(ARRAY['dp_owner', 'dp_app']) AS r
  WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'CMS S1: database roles missing (%); ADR-012A must be applied first', missing;
  END IF;
END $$;

-- ===========================================================================================
-- Part 1: table and indexes (generated)
-- ===========================================================================================

-- CreateEnum
CREATE TYPE "CmsPageKind" AS ENUM ('DESIGN', 'TEMPLATE', 'FRAGMENT');

-- CreateTable
CREATE TABLE "CmsPage" (
    "id" UUID NOT NULL,
    "siteId" UUID NOT NULL,
    "kind" "CmsPageKind" NOT NULL,
    "templateKey" VARCHAR(80) NOT NULL,
    "path" VARCHAR(120),
    "locale" VARCHAR(35) NOT NULL,
    "title" VARCHAR(200) NOT NULL,
    "seoTitle" VARCHAR(120),
    "seoDescription" VARCHAR(320),
    "noindex" BOOLEAN NOT NULL DEFAULT false,
    "content" JSONB NOT NULL,
    "schemaVersion" INTEGER NOT NULL DEFAULT 1,
    "version" INTEGER NOT NULL DEFAULT 1,
    "createdById" UUID NOT NULL,
    "updatedById" UUID NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "CmsPage_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "CmsPage_siteId_kind_idx" ON "CmsPage"("siteId", "kind");

-- CreateIndex
CREATE UNIQUE INDEX "CmsPage_siteId_path_key" ON "CmsPage"("siteId", "path");

-- CreateIndex
CREATE UNIQUE INDEX "CmsPage_registry_siteId_templateKey_key" ON "CmsPage"("siteId", "templateKey") WHERE (kind <> 'TEMPLATE'::"CmsPageKind");

-- AddForeignKey
ALTER TABLE "CmsPage" ADD CONSTRAINT "CmsPage_siteId_fkey" FOREIGN KEY ("siteId") REFERENCES "Site"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPage" ADD CONSTRAINT "CmsPage_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPage" ADD CONSTRAINT "CmsPage_updatedById_fkey" FOREIGN KEY ("updatedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- ===========================================================================================
-- Part 2: consistency (CHECK)
-- ===========================================================================================

ALTER TABLE "CmsPage"
  ADD CONSTRAINT "CmsPage_path_format"
    CHECK ("path" IS NULL OR "path" ~ '^/([a-z0-9]+(-[a-z0-9]+)*)?$'),
  -- Fragments (navigation, footer) have no URL; every page has one.
  ADD CONSTRAINT "CmsPage_fragment_path" CHECK (("kind" = 'FRAGMENT') = ("path" IS NULL)),
  -- TEMPLATE pages use the standard template and never take the home page, an app route or a
  -- two-letter (locale) segment; contracts CMS_RESERVED_SLUGS is the same list.
  ADD CONSTRAINT "CmsPage_template_path" CHECK (
    "kind" <> 'TEMPLATE' OR (
      "templateKey" = 'standard'
      AND "path" <> '/'
      AND split_part("path", '/', 2) !~ '^[a-z]{2}$'
      AND split_part("path", '/', 2) NOT IN (
        'api', 'demo', 'lead-form', 'preview', 'privacy', 'product-documents', 'product-images',
        'products', 'robots', 'search', 'sitemap'
      )
    )
  ),
  -- DESIGN pages and fragments carry a registry key ("bv.home", "corporate.home", ...).
  ADD CONSTRAINT "CmsPage_registry_key"
    CHECK ("kind" = 'TEMPLATE' OR "templateKey" ~ '^(bv|corporate)\.[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "CmsPage_title_trimmed"
    CHECK ("title" = btrim("title") AND length("title") >= 1),
  ADD CONSTRAINT "CmsPage_seo_trimmed" CHECK (
    ("seoTitle" IS NULL OR ("seoTitle" = btrim("seoTitle") AND length("seoTitle") >= 1))
    AND ("seoDescription" IS NULL
      OR ("seoDescription" = btrim("seoDescription") AND length("seoDescription") >= 1))
  ),
  ADD CONSTRAINT "CmsPage_locale_format"
    CHECK ("locale" ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$'),
  ADD CONSTRAINT "CmsPage_content_object" CHECK (jsonb_typeof("content") = 'object'),
  ADD CONSTRAINT "CmsPage_version_positive" CHECK ("version" >= 1 AND "schemaVersion" >= 1);

-- ===========================================================================================
-- Part 3: privileges
-- ===========================================================================================

-- S1 has no page deletion; a later stage that needs it grants it with its own guard.
REVOKE DELETE ON TABLE "CmsPage" FROM dp_app;
